SELECT ROUND(100.0 * (COUNT(*) - COUNT(order_id)) / NULLIF(COUNT(*), 0), 2)
       AS percentage_without_order
FROM tickets;

SELECT COALESCE(SUM(
    o.shipping_minor + COALESCE((
        SELECT SUM(oi.quantity * oi.unit_price_minor)
